// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/types.h>

/* Normal inputs: identical strings compare equal. */
static void agent_test_identical(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 10), 0);
}

/* Normal inputs: letters differing only in case compare equal. */
static void agent_test_equal_ignoring_case(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo WoRLD", "hello world", 11), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcXYZ", "ABCxyz", 6), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "z", 1), 0);
}

/* Normal inputs: sign of the result for ordered differing strings. */
static void agent_test_ordering(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("banana", "apple", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ABC", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABD", "abc", 3), 0);
}

/* Exact return value is the difference of the folded differing bytes. */
static void agent_test_exact_difference(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "c", 1), -2);
	KUNIT_EXPECT_EQ(test, strncasecmp("c", "a", 1), 2);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 3), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abc", 3), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "B", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("C", "a", 1), 2);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "abc", 3), -99);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ab", 3), 99);
}

/* len == 0 never looks at the strings and always returns 0. */
static void agent_test_len_zero(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "x", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("x", "", 0), 0);
}

/* len == 1 compares only the first byte. */
static void agent_test_len_one(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("b", "a", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ac", 1), 0);
}

/* Boundary: a mismatch at index len-1 is seen; one at index len is not. */
static void agent_test_len_boundary(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abce", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abce", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdef", "abcdeg", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdef", "abcdeg", 6), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdef", "abcdeg", 7), -1);
}

/* Boundary: len larger than either string stops at the terminator. */
static void agent_test_len_exceeds_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "ab", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "abc", 100), -99);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ab", 100), 99);
	KUNIT_EXPECT_EQ(test, strncasecmp("ab", "abc", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abc", SIZE_MAX), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", SIZE_MAX), -1);
}

/* Boundary: empty strings. */
static void agent_test_empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 5), -97);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 5), 97);
	KUNIT_EXPECT_LT(test, strncasecmp("", "A", 1), 0);
}

/* A NUL byte terminates the comparison even when len is larger. */
static void agent_test_embedded_nul(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a\0b", "a\0c", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a\0", "a", 2), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a\0x", "a\0y", 1), 0);
}

/* Bytes adjacent to the letter ranges must not be folded. */
static void agent_test_non_letter_boundaries(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "`", 1), -32);
	KUNIT_EXPECT_EQ(test, strncasecmp("@", "A", 1), -33);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "[", 1), 31);
	KUNIT_EXPECT_EQ(test, strncasecmp("_", "`", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("{", "[", 1), 32);
	KUNIT_EXPECT_EQ(test, strncasecmp("0", "/", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("9", ":", 1), -1);
}

/* Bytes >= 0x80 compare as unsigned and are not case-folded. */
static void agent_test_high_bytes(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("\xff", "\x01", 1), 254);
	KUNIT_EXPECT_EQ(test, strncasecmp("\x01", "\xff", 1), -254);
	KUNIT_EXPECT_EQ(test, strncasecmp("\x80", "\x7f", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("\xc1", "\xc1", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\xe0", "\x61", 1), 0);
}

/* The first differing position decides the result. */
static void agent_test_first_difference_wins(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abXd", "abyd", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("abXa", "abyz", 4), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("xbcd", "abcd", 4), 23);
}

/* Antisymmetry: swapping arguments flips the sign of the result. */
static void agent_test_symmetry(struct kunit *test)
{
	static const char *const strs[] = {
		"", "a", "A", "ab", "AB", "abc", "Abd", "@", "`", "Z", "[", "\xff",
	};
	size_t i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			int ab = strncasecmp(strs[i], strs[j], 3);
			int ba = strncasecmp(strs[j], strs[i], 3);

			KUNIT_EXPECT_EQ(test, (ab > 0) - (ab < 0),
					-((ba > 0) - (ba < 0)));
		}
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_identical),
	KUNIT_CASE(agent_test_equal_ignoring_case),
	KUNIT_CASE(agent_test_ordering),
	KUNIT_CASE(agent_test_exact_difference),
	KUNIT_CASE(agent_test_len_zero),
	KUNIT_CASE(agent_test_len_one),
	KUNIT_CASE(agent_test_len_boundary),
	KUNIT_CASE(agent_test_len_exceeds_strings),
	KUNIT_CASE(agent_test_empty_strings),
	KUNIT_CASE(agent_test_embedded_nul),
	KUNIT_CASE(agent_test_non_letter_boundaries),
	KUNIT_CASE(agent_test_high_bytes),
	KUNIT_CASE(agent_test_first_difference_wins),
	KUNIT_CASE(agent_test_symmetry),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strncasecmp");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/string.h>

static void strcspn_empty_string(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
}

static void strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("abc", ""), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", ""), (size_t)11);
}

static void strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyz"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "d"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), (size_t)1);
}

static void strcspn_match_first_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
}

static void strcspn_match_last_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "f"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyzc"), (size_t)2);
}

static void strcspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "b"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "d"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "="), (size_t)3);
}

static void strcspn_returns_first_occurrence(struct kunit *test)
{
	/* Several reject characters appear in s; the earliest one wins. */
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "cb"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("xxyxx", "y"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "ab"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("12345", "54"), (size_t)3);
}

static void strcspn_multi_char_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello, world", ",!"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("path/to/file", "/."), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("no-delims", " \t\n"), (size_t)9);
}

static void strcspn_repeated_non_reject_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("zzzzzzzz", "a"), (size_t)8);
	KUNIT_EXPECT_EQ(test, strcspn("zzzzzzzza", "a"), (size_t)8);
	KUNIT_EXPECT_EQ(test, strcspn("aaaaaaaa", "a"), (size_t)0);
}

static void strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "h"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "H"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("Hello", "lo"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ABCdef", "cdef"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("ABCdef", "CDEF"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ABCdef", "XYZ"), (size_t)6);
}

static void strcspn_high_bit_bytes(struct kunit *test)
{
	/* Bytes >= 0x80 must compare as unsigned characters. */
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff\x01", "\xff"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff\x01", "\x80"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("\x80\xff\x01", "\x01"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("\x01\x7f", "\x80\xff"), (size_t)2);
}

static void strcspn_stops_at_terminator(struct kunit *test)
{
	/* The scan must end at the NUL in s, not read the bytes after it. */
	static const char buf[] = "ab\0c";

	KUNIT_EXPECT_EQ(test, strcspn(buf, "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(buf, ""), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "xyz"), (size_t)2);
}

static void strcspn_identical_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "abc"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("x", "x"), (size_t)0);
}

static void strcspn_every_byte_value(struct kunit *test)
{
	/*
	 * s holds every non-NUL byte value once, in ascending order.
	 * Rejecting the byte at index k must yield exactly k.
	 */
	char s[256];
	char reject[2] = { 0, 0 };
	int i;

	for (i = 0; i < 255; i++)
		s[i] = (char)(i + 1);
	s[255] = '\0';

	for (i = 0; i < 255; i++) {
		reject[0] = s[i];
		KUNIT_EXPECT_EQ_MSG(test, strcspn(s, reject), (size_t)i,
				    "reject byte 0x%02x", (unsigned char)s[i]);
	}
}

static void strcspn_long_string(struct kunit *test)
{
	const size_t len = 4096;
	char *buf;

	buf = kunit_kzalloc(test, len + 2, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, buf);

	memset(buf, 'a', len);
	buf[len] = 'z';
	buf[len + 1] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn(buf, "z"), len);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), len + 1);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "az"), (size_t)0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strcspn_empty_string),
	KUNIT_CASE(strcspn_empty_reject),
	KUNIT_CASE(strcspn_no_match),
	KUNIT_CASE(strcspn_match_first_char),
	KUNIT_CASE(strcspn_match_last_char),
	KUNIT_CASE(strcspn_match_middle),
	KUNIT_CASE(strcspn_returns_first_occurrence),
	KUNIT_CASE(strcspn_multi_char_reject),
	KUNIT_CASE(strcspn_repeated_non_reject_chars),
	KUNIT_CASE(strcspn_case_sensitive),
	KUNIT_CASE(strcspn_high_bit_bytes),
	KUNIT_CASE(strcspn_stops_at_terminator),
	KUNIT_CASE(strcspn_identical_strings),
	KUNIT_CASE(strcspn_every_byte_value),
	KUNIT_CASE(strcspn_long_string),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/*
 * Expected values below are derived by hand from the algorithm in
 * string_get_size(): blocks are reduced by the divisor (1000 or 1024)
 * until the value is below the divisor, the remainder is rounded to
 * three significant figures, and the return value is the full would-be
 * length of the output, not the number of bytes actually written.
 */

static void check_size(struct kunit *test, u64 size, u64 blk_size,
		       enum string_size_units units, const char *expected)
{
	char buf[32];
	int ret;

	ret = string_get_size(size, blk_size, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, expected);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(expected));
}

static void test_zero_size(struct kunit *test)
{
	check_size(test, 0, 1, STRING_UNITS_10, "0 B");
	check_size(test, 0, 1, STRING_UNITS_2, "0 B");
	check_size(test, 0, 1024, STRING_UNITS_2, "0 B");
	check_size(test, 0, 1ULL << 40, STRING_UNITS_10, "0 B");
}

static void test_zero_blk_size(struct kunit *test)
{
	/* A zero block size forces the size to zero, whatever it was */
	check_size(test, 1500, 0, STRING_UNITS_10, "0 B");
	check_size(test, 1024, 0, STRING_UNITS_2, "0 B");
	check_size(test, 1ULL << 63, 0, STRING_UNITS_2, "0 B");
}

static void test_bytes_range(struct kunit *test)
{
	check_size(test, 1, 1, STRING_UNITS_10, "1.00 B");
	check_size(test, 1, 1, STRING_UNITS_2, "1.00 B");
	check_size(test, 500, 1, STRING_UNITS_10, "500 B");
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	check_size(test, 1000, 1, STRING_UNITS_2, "1000 B");
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
}

static void test_si_unit_boundary(struct kunit *test)
{
	/* 999 is the last value that stays in bytes, 1000 becomes kB */
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	check_size(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1001, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 999499, 1, STRING_UNITS_10, "999 kB");
	check_size(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check_size(test, 1000000000, 1, STRING_UNITS_10, "1.00 GB");
}

static void test_binary_unit_boundary(struct kunit *test)
{
	/* 1023 is the last value that stays in bytes, 1024 becomes KiB */
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
	check_size(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1048575, 1, STRING_UNITS_2, "1024 KiB");
	check_size(test, 1048576, 1, STRING_UNITS_2, "1.00 MiB");
	check_size(test, 1073741824, 1, STRING_UNITS_2, "1.00 GiB");
}

static void test_si_rounding(struct kunit *test)
{
	/* Three significant figures, half rounds up */
	check_size(test, 1500, 1, STRING_UNITS_10, "1.50 kB");
	check_size(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	check_size(test, 1995, 1, STRING_UNITS_10, "2.00 kB");
	check_size(test, 10049, 1, STRING_UNITS_10, "10.0 kB");
	check_size(test, 10050, 1, STRING_UNITS_10, "10.1 kB");
	check_size(test, 999000, 1, STRING_UNITS_10, "999 kB");
}

static void test_binary_rounding(struct kunit *test)
{
	check_size(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	check_size(test, 2042, 1, STRING_UNITS_2, "1.99 KiB");
	check_size(test, 2043, 1, STRING_UNITS_2, "2.00 KiB");
	check_size(test, 10752, 1, STRING_UNITS_2, "10.5 KiB");
}

static void test_rounding_carry_into_unit(struct kunit *test)
{
	/* Three-digit integer part: the rounding carry must bump 100 -> 101 */
	check_size(test, 100499, 1, STRING_UNITS_10, "100 kB");
	check_size(test, 100500, 1, STRING_UNITS_10, "101 kB");
	check_size(test, 102911, 1, STRING_UNITS_2, "100 KiB");
	check_size(test, 102912, 1, STRING_UNITS_2, "101 KiB");
}

static void test_block_size_scaling(struct kunit *test)
{
	check_size(test, 1, 1000, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1000, 1000, STRING_UNITS_10, "1.00 MB");
	check_size(test, 3, 1024, STRING_UNITS_2, "3.00 KiB");
	check_size(test, 2048, 512, STRING_UNITS_10, "1.05 MB");
	check_size(test, 2048, 512, STRING_UNITS_2, "1.00 MiB");
}

static void test_block_size_above_32_bits(struct kunit *test)
{
	/* blk_size >= 2^32 goes through its own reduction loop */
	check_size(test, 1, 1ULL << 32, STRING_UNITS_2, "4.00 GiB");
	check_size(test, 1, 1ULL << 32, STRING_UNITS_10, "4.29 GB");
}

static void test_size_above_32_bits(struct kunit *test)
{
	/* size >= 2^32 goes through its own reduction loop */
	check_size(test, 1ULL << 32, 1, STRING_UNITS_2, "4.00 GiB");
	check_size(test, 1ULL << 32, 1, STRING_UNITS_10, "4.29 GB");
	check_size(test, 1ULL << 40, 1, STRING_UNITS_2, "1.00 TiB");
	check_size(test, 1000000000000ULL, 1, STRING_UNITS_10, "1.00 TB");
	check_size(test, 1ULL << 40, 1, STRING_UNITS_10, "1.10 TB");
}

static void test_largest_units(struct kunit *test)
{
	/* Top of the table: EiB/EB, ZiB, YiB and the 2^63 extremes */
	check_size(test, 1ULL << 60, 1, STRING_UNITS_2, "1.00 EiB");
	check_size(test, 1ULL << 63, 1, STRING_UNITS_2, "8.00 EiB");
	check_size(test, 1ULL << 63, 1, STRING_UNITS_10, "9.22 EB");
	check_size(test, 1000000000000000000ULL, 1, STRING_UNITS_10, "1.00 EB");
	check_size(test, 1024, 1ULL << 60, STRING_UNITS_2, "1.00 ZiB");
	check_size(test, 1ULL << 40, 1ULL << 40, STRING_UNITS_2, "1.00 YiB");
}

static void test_unknown_unit_past_table(struct kunit *test)
{
	/* The unit table has 9 entries; index 9 and beyond print "UNK" */
	check_size(test, 1ULL << 40, 1ULL << 50, STRING_UNITS_2, "1.00 UNKB");
	check_size(test, 1ULL << 63, 1ULL << 63, STRING_UNITS_2, "64.0 UNKB");
}

static void test_unit_base_selection(struct kunit *test)
{
	/* The same value is reported differently in base 10 and base 2 */
	check_size(test, 1024, 1, STRING_UNITS_10, "1.02 kB");
	check_size(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
}

static void test_no_space_flag(struct kunit *test)
{
	check_size(test, 1500, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE,
		   "1.50kB");
	check_size(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE,
		   "1.00KiB");
}

static void test_no_bytes_flag(struct kunit *test)
{
	check_size(test, 1500, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES,
		   "1.50 k");
	check_size(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES,
		   "1.00 Ki");
}

static void test_no_space_and_no_bytes(struct kunit *test)
{
	check_size(test, 1500, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		   "1.50k");
	check_size(test, 1024, 1,
		   STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		   "1.00Ki");
}

static void test_truncated_output(struct kunit *test)
{
	char buf[16];
	int ret;

	/* Return value is the untruncated length; output is cut to len - 1 */
	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1500, 1, STRING_UNITS_10, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.5");
	KUNIT_EXPECT_EQ(test, buf[4], 'x');

	ret = string_get_size(1500, 1, STRING_UNITS_10, buf, 7);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.50 k");

	ret = string_get_size(1500, 1, STRING_UNITS_10, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.50 kB");

	ret = string_get_size(1500, 1, STRING_UNITS_10, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "");

	memset(buf, 'x', sizeof(buf));
	ret = string_get_size(1500, 1, STRING_UNITS_10, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], 'x');
}

