// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Covers string_escape_mem(): every escape class, the @only and
 * %ESCAPE_APPEND handling, exhaustive single-byte checks, and the
 * destination-size boundary (truncation, exact fit, partial sequences).
 */
#include <kunit/test.h>
#include <linux/ctype.h>
#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define CANARY	0xAA
#define BUF_SZ	64

/*
 * Run string_escape_mem() into a canary-filled buffer of @osz bytes and
 * check the return value, the bytes written, and that nothing at or past
 * @osz was touched.
 */
static void check_escape_osz(struct kunit *test, const char *src, size_t isz,
			     unsigned int flags, const char *only, size_t osz,
			     const char *expected, size_t elen)
{
	char buf[BUF_SZ];
	size_t i;
	int ret;

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, osz, flags, only);
	KUNIT_ASSERT_EQ_MSG(test, ret, (int)elen, "osz %zu", osz);
	KUNIT_ASSERT_MEMEQ_MSG(test, buf, expected, min(osz, elen),
			       "osz %zu", osz);
	for (i = osz; i < sizeof(buf); i++)
		KUNIT_ASSERT_EQ_MSG(test, (unsigned char)buf[i], CANARY,
				    "osz %zu, written at %zu", osz, i);
}

static void check_escape(struct kunit *test, const char *src, size_t isz,
			 unsigned int flags, const char *only,
			 const char *expected, size_t elen)
{
	check_escape_osz(test, src, isz, flags, only, BUF_SZ, expected, elen);
}

/*
 * Check the single-byte input @c. Expected output is the byte itself when
 * @pass is set, otherwise "\NNN" (octal) or "\xHH" (hex) as selected by @hex.
 */
static void check_byte(struct kunit *test, unsigned int c, unsigned int flags,
		       bool hex, bool pass)
{
	char buf[BUF_SZ];
	char exp[8];
	char src = (char)c;
	size_t elen;
	int ret;

	if (pass) {
		exp[0] = (char)c;
		elen = 1;
	} else if (hex) {
		elen = scnprintf(exp, sizeof(exp), "\\x%02x", c);
	} else {
		elen = scnprintf(exp, sizeof(exp), "\\%03o", c);
	}

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(&src, 1, buf, sizeof(buf), flags, NULL);
	KUNIT_ASSERT_EQ_MSG(test, ret, (int)elen, "byte 0x%02x flags 0x%x",
			    c, flags);
	KUNIT_ASSERT_MEMEQ_MSG(test, buf, exp, elen, "byte 0x%02x flags 0x%x",
			       c, flags);
}

static void escape_size_query(struct kunit *test)
{
	char buf[BUF_SZ];
	int ret;

	/* No flags: output length equals input length */
	KUNIT_EXPECT_EQ(test, string_escape_mem("hello", 5, NULL, 0, 0, NULL), 5);
	/* "\n" becomes "\\n" */
	KUNIT_EXPECT_EQ(test, string_escape_mem("a\nb", 3, NULL, 0,
						ESCAPE_SPACE, NULL), 4);
	/* One byte becomes four with octal or hex */
	KUNIT_EXPECT_EQ(test, string_escape_mem("\x01", 1, NULL, 0,
						ESCAPE_OCTAL, NULL), 4);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\x01", 1, NULL, 0,
						ESCAPE_HEX, NULL), 4);
	/* Two specials, each two bytes */
	KUNIT_EXPECT_EQ(test, string_escape_mem("\\\"", 2, NULL, 0,
						ESCAPE_SPECIAL, NULL), 4);
	/* Empty input */
	KUNIT_EXPECT_EQ(test, string_escape_mem("", 0, NULL, 0, ESCAPE_ANY, NULL), 0);

	/* osz of zero with a real buffer writes nothing */
	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem("a\nb", 3, buf, 0, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], CANARY);
}

static void escape_passthrough_without_flags(struct kunit *test)
{
	static const char src[] = "a\n\"\\\xe9z\x7f";

	check_escape(test, src, sizeof(src) - 1, 0, NULL, src, sizeof(src) - 1);
}

static void escape_empty_input(struct kunit *test)
{
	check_escape(test, "", 0, ESCAPE_ANY, NULL, "", 0);
}

static void escape_space_class(struct kunit *test)
{
	check_escape(test, "\n\r\t\v\f", 5, ESCAPE_SPACE, NULL,
		     "\\n\\r\\t\\v\\f", 10);
	/* A plain space is not part of the class */
	check_escape(test, "a b", 3, ESCAPE_SPACE, NULL, "a b", 3);
}

static void escape_special_class(struct kunit *test)
{
	/* \\ \" \a \e (0x1b) */
	check_escape(test, "\\\"\a\x1b", 4, ESCAPE_SPECIAL, NULL,
		     "\\\\\\\"\\a\\e", 8);
	/* Single quote is not part of the class */
	check_escape(test, "'", 1, ESCAPE_SPECIAL, NULL, "'", 1);
}

static void escape_null_class(struct kunit *test)
{
	static const char src[] = { 'a', 0, 'b' };

	check_escape(test, src, sizeof(src), ESCAPE_NULL, NULL, "a\\0b", 4);
}

static void escape_octal_all_bytes(struct kunit *test)
{
	unsigned int c;

	for (c = 0; c < 256; c++)
		check_byte(test, c, ESCAPE_OCTAL, false, false);
}

static void escape_hex_all_bytes(struct kunit *test)
{
	unsigned int c;

	for (c = 0; c < 256; c++)
		check_byte(test, c, ESCAPE_HEX, true, false);
}

static void escape_octal_takes_precedence_over_hex(struct kunit *test)
{
	check_byte(test, 0x01, ESCAPE_OCTAL | ESCAPE_HEX, false, false);
	check_byte(test, 0xff, ESCAPE_OCTAL | ESCAPE_HEX, false, false);
}

static void escape_any_mixed(struct kunit *test)
{
	static const char src[] = { 0, '\n', '"', 0x01, 'a' };

	/* OCTAL is the catch-all, so the plain 'a' is escaped too */
	check_escape(test, src, sizeof(src), ESCAPE_ANY, NULL,
		     "\\0\\n\\\"\\001\\141", 14);
}

static void escape_text_example(struct kunit *test)
{
	const char *src = "Hello\tWorld\n\"quoted\"\\";

	check_escape(test, src, strlen(src), ESCAPE_SPACE | ESCAPE_SPECIAL, NULL,
		     "Hello\\tWorld\\n\\\"quoted\\\"\\\\", 26);
}

static void escape_np_all_bytes(struct kunit *test)
{
	unsigned int c;

	/* Bytes that isprint() accepts pass through, including Latin-1 */
	for (c = 0; c < 256; c++)
		check_byte(test, c, ESCAPE_NP | ESCAPE_OCTAL, false,
			   isprint(c));
}

static void escape_na_all_bytes(struct kunit *test)
{
	unsigned int c;

	/* Any 7-bit ASCII byte passes through, including controls and DEL */
	for (c = 0; c < 256; c++)
		check_byte(test, c, ESCAPE_NA | ESCAPE_OCTAL, false, c < 0x80);
}

static void escape_nap_all_bytes(struct kunit *test)
{
	unsigned int c;

	/* Printable and ASCII passes through: 0x20..0x7e only */
	for (c = 0; c < 256; c++)
		check_byte(test, c, ESCAPE_NAP | ESCAPE_OCTAL, false,
			   isascii(c) && isprint(c));
}

static void escape_nap_overrides_special(struct kunit *test)
{
	/* '"' and '\' are printable, so NAP passes them through unescaped */
	check_escape(test, "\"\\", 2, ESCAPE_NAP | ESCAPE_SPECIAL, NULL,
		     "\"\\", 2);
	/* BEL is not printable, so it falls through to the SPECIAL class */
	check_escape(test, "\"\a", 2, ESCAPE_NAP | ESCAPE_SPECIAL, NULL,
		     "\"\\a", 3);
}

static void escape_embedded_nul_uses_isz(struct kunit *test)
{
	static const char src[] = { 'a', 0, 'b' };

	/* Length is taken from isz, not strlen() */
	check_escape(test, src, 3, ESCAPE_OCTAL, NULL, "\\141\\000\\142", 12);
	check_escape(test, src, 3, 0, NULL, src, 3);
	check_escape(test, src, 1, ESCAPE_OCTAL, NULL, "\\141", 4);
	check_escape(test, src, 2, 0, NULL, src, 2);
}

static void escape_only_limits_escaping(struct kunit *test)
{
	static const char src[] = { 'a', '\n', '\\', '"' };

	/* Only '\n' is in @only, so only it gets escaped by SPACE */
	check_escape(test, src, sizeof(src), ESCAPE_SPACE | ESCAPE_SPECIAL, "\n",
		     "a\\n\\\"", 5);
	/* 'a' is in @only but not in SPACE; '\n' is not in @only, so it
	 * passes through raw */
	check_escape(test, "a\n", 2, ESCAPE_SPACE, "a", "a\n", 2);
}

static void escape_only_empty_is_ignored(struct kunit *test)
{
	check_escape(test, "a\n", 2, ESCAPE_SPACE, "", "a\\n", 3);
	check_escape(test, "a\n", 2, ESCAPE_SPACE, NULL, "a\\n", 3);
}

static void escape_append_escapes_dictionary_chars(struct kunit *test)
{
	/* With APPEND, 'a' from @only is escaped by HEX; 'b' is printable */
	check_escape(test, "ab", 2, ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, "a",
		     "\\x61b", 5);
}

static void escape_append_absent_keeps_dictionary_chars_raw(struct kunit *test)
{
	/* Without APPEND, printable 'a' from @only passes through */
	check_escape(test, "ab", 2, ESCAPE_NP | ESCAPE_HEX, "a", "ab", 2);
}

static void escape_truncation_keeps_full_length(struct kunit *test)
{
	/* Return value is the full length, even though only 3 bytes fit */
	check_escape_osz(test, "abcdef", 6, 0, NULL, 3, "abc", 6);
	/* "\n\n" is 4 bytes; only the first escape plus one byte fits */
	check_escape_osz(test, "\n\n", 2, ESCAPE_SPACE, NULL, 3,
			 "\\n\\", 4);
}

static void escape_exact_fit_no_overflow(struct kunit *test)
{
	/* "ab\\n" is exactly 4 bytes; osz 4 holds it with no terminator */
	check_escape_osz(test, "ab\n", 3, ESCAPE_SPACE, NULL, 4, "ab\\n", 4);
}

static void escape_partial_sequence_boundary(struct kunit *test)
{
	static const char hex_src[] = { 0x01 };

	/* Sequences are written all-or-nothing per byte, bounded by osz */
	check_escape_osz(test, hex_src, 1, ESCAPE_HEX, NULL, 1, "\\", 4);
	check_escape_osz(test, hex_src, 1, ESCAPE_HEX, NULL, 2, "\\x", 4);
	check_escape_osz(test, hex_src, 1, ESCAPE_HEX, NULL, 3, "\\x0", 4);
	check_escape_osz(test, hex_src, 1, ESCAPE_HEX, NULL, 4, "\\x01", 4);
}

static void escape_boundary_sweep(struct kunit *test)
{
	static const char src[] = { 'a', '\n', '"', 0x01, 'z' };
	/* HEX is the catch-all, so 'a' and 'z' are escaped as well */
	static const char exp[] = "\\x61\\n\\\"\\x01\\x7a";
	size_t osz;

	/* Every destination size from 0 up to past the full output */
	for (osz = 0; osz <= sizeof(exp); osz++)
		check_escape_osz(test, src, sizeof(src),
				 ESCAPE_SPACE | ESCAPE_SPECIAL | ESCAPE_HEX,
				 NULL, osz, exp, sizeof(exp) - 1);
}

static void escape_zero_osz_and_null_dst(struct kunit *test)
{
	int ret;

	/* A NULL dst with osz 0 is a valid size query */
	ret = string_escape_mem("\n", 1, NULL, 0, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	/* isz of 0 never writes */
	ret = string_escape_mem("\n", 0, NULL, 0, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(escape_size_query),
	KUNIT_CASE(escape_passthrough_without_flags),
	KUNIT_CASE(escape_empty_input),
	KUNIT_CASE(escape_space_class),
	KUNIT_CASE(escape_special_class),
	KUNIT_CASE(escape_null_class),
	KUNIT_CASE(escape_octal_all_bytes),
	KUNIT_CASE(escape_hex_all_bytes),
	KUNIT_CASE(escape_octal_takes_precedence_over_hex),
	KUNIT_CASE(escape_any_mixed),
	KUNIT_CASE(escape_text_example),
	KUNIT_CASE(escape_np_all_bytes),
	KUNIT_CASE(escape_na_all_bytes),
	KUNIT_CASE(escape_nap_all_bytes),
	KUNIT_CASE(escape_nap_overrides_special),
	KUNIT_CASE(escape_embedded_nul_uses_isz),
	KUNIT_CASE(escape_only_limits_escaping),
	KUNIT_CASE(escape_only_empty_is_ignored),
	KUNIT_CASE(escape_append_escapes_dictionary_chars),
	KUNIT_CASE(escape_append_absent_keeps_dictionary_chars_raw),
	KUNIT_CASE(escape_truncation_keeps_full_length),
	KUNIT_CASE(escape_exact_fit_no_overflow),
	KUNIT_CASE(escape_partial_sequence_boundary),
	KUNIT_CASE(escape_boundary_sweep),
	KUNIT_CASE(escape_zero_osz_and_null_dst),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

