// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Covers string_unescape() from lib/string_helpers.c: each escape class,
 * the per-flag gating, digit-count limits, unknown and malformed escapes,
 * destination size boundaries, and in-place use.
 */
#include <kunit/test.h>
#include <linux/module.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define DST_LEN 64

/*
 * Run string_unescape() on a copy of @in and check the returned length, the
 * decoded bytes, NUL termination at @exp_len, and that nothing at or past
 * @size was written (when @size is non-zero).
 */
static void check_unescape(struct kunit *test, const char *in, size_t size,
			   unsigned int flags, const char *exp, size_t exp_len)
{
	char src[DST_LEN];
	char dst[DST_LEN];
	bool clobbered = false;
	size_t i;
	int ret;

	KUNIT_ASSERT_LT(test, strlen(in), sizeof(src));
	strscpy(src, in, sizeof(src));
	memset(dst, 'X', sizeof(dst));

	ret = string_unescape(src, dst, size, flags);

	KUNIT_EXPECT_EQ(test, ret, (int)exp_len);
	KUNIT_EXPECT_EQ(test, memcmp(dst, exp, exp_len), 0);
	KUNIT_EXPECT_EQ(test, dst[exp_len], '\0');

	if (size && size < DST_LEN) {
		for (i = size; i < DST_LEN; i++)
			clobbered |= dst[i] != 'X';
		KUNIT_EXPECT_FALSE(test, clobbered);
	}
}

/* @exp is a string literal; its length excludes the terminator but keeps
 * any embedded NULs, so sizeof(exp) - 1 is the exact decoded length.
 */
#define EXPECT_UNESCAPE(test, in, size, flags, exp)			\
	check_unescape((test), (in), (size), (flags), (exp), sizeof(exp) - 1)

static void agent_plain_text(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "hello world", 0, UNESCAPE_ANY, "hello world");
	EXPECT_UNESCAPE(test, "100% of 'x' & \"y\"", 0, UNESCAPE_ANY,
			"100% of 'x' & \"y\"");
	EXPECT_UNESCAPE(test, "hello", 0, 0, "hello");
}

static void agent_empty_string(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "", 0, UNESCAPE_ANY, "");
	EXPECT_UNESCAPE(test, "", 1, UNESCAPE_ANY, "");
	EXPECT_UNESCAPE(test, "", 2, UNESCAPE_ANY, "");
}

static void agent_space_escapes(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\f", 0, UNESCAPE_SPACE, "\f");
	EXPECT_UNESCAPE(test, "\\n", 0, UNESCAPE_SPACE, "\n");
	EXPECT_UNESCAPE(test, "\\r", 0, UNESCAPE_SPACE, "\r");
	EXPECT_UNESCAPE(test, "\\t", 0, UNESCAPE_SPACE, "\t");
	EXPECT_UNESCAPE(test, "\\v", 0, UNESCAPE_SPACE, "\v");
	EXPECT_UNESCAPE(test, "\\f\\n\\r\\t\\v", 0, UNESCAPE_SPACE,
			"\f\n\r\t\v");
	EXPECT_UNESCAPE(test, "\\f\\n\\r\\t\\v", 0, UNESCAPE_ANY,
			"\f\n\r\t\v");
}

static void agent_special_escapes(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\\"", 0, UNESCAPE_SPECIAL, "\"");
	EXPECT_UNESCAPE(test, "\\\\", 0, UNESCAPE_SPECIAL, "\\");
	EXPECT_UNESCAPE(test, "\\a", 0, UNESCAPE_SPECIAL, "\a");
	EXPECT_UNESCAPE(test, "\\e", 0, UNESCAPE_SPECIAL, "\x1b");
	EXPECT_UNESCAPE(test, "\\\"\\\\\\a\\e", 0, UNESCAPE_SPECIAL,
			"\"\\\a\x1b");
}

static void agent_octal_escapes(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\1", 0, UNESCAPE_OCTAL, "\x01");
	EXPECT_UNESCAPE(test, "\\40", 0, UNESCAPE_OCTAL, " ");
	EXPECT_UNESCAPE(test, "\\060", 0, UNESCAPE_OCTAL, "0");
	EXPECT_UNESCAPE(test, "\\101", 0, UNESCAPE_OCTAL, "A");
	EXPECT_UNESCAPE(test, "\\377", 0, UNESCAPE_OCTAL, "\xff");
	EXPECT_UNESCAPE(test, "\\375", 0, UNESCAPE_OCTAL, "\xfd");
}

static void agent_octal_digit_limits(struct kunit *test)
{
	/* At most three octal digits are consumed: \123 is 'S', then '4'. */
	EXPECT_UNESCAPE(test, "\\1234", 0, UNESCAPE_OCTAL, "S4");
	/* '8' and '9' are not octal digits. */
	EXPECT_UNESCAPE(test, "\\19", 0, UNESCAPE_OCTAL, "\x01" "9");
	EXPECT_UNESCAPE(test, "\\8", 0, UNESCAPE_OCTAL, "\\8");
}

static void agent_octal_embedded_nul(struct kunit *test)
{
	/* \0 decodes to a real NUL byte; the length still counts it. */
	EXPECT_UNESCAPE(test, "a\\0b", 0, UNESCAPE_OCTAL, "a\0b");
}

static void agent_hex_escapes(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\x4", 0, UNESCAPE_HEX, "\x04");
	EXPECT_UNESCAPE(test, "\\x41", 0, UNESCAPE_HEX, "A");
	EXPECT_UNESCAPE(test, "\\xff", 0, UNESCAPE_HEX, "\xff");
	EXPECT_UNESCAPE(test, "\\xFF", 0, UNESCAPE_HEX, "\xff");
	EXPECT_UNESCAPE(test, "\\xaB", 0, UNESCAPE_HEX, "\xab");
	EXPECT_UNESCAPE(test, "\\x00", 0, UNESCAPE_HEX, "\0");
	/* Only two hex digits are consumed. */
	EXPECT_UNESCAPE(test, "\\x41Z", 0, UNESCAPE_HEX, "AZ");
	EXPECT_UNESCAPE(test, "\\x4G", 0, UNESCAPE_HEX, "\x04" "G");
}

static void agent_hex_malformed(struct kunit *test)
{
	/* No hex digit after \x: the backslash and 'x' are kept. */
	EXPECT_UNESCAPE(test, "\\xG", 0, UNESCAPE_HEX, "\\xG");
	EXPECT_UNESCAPE(test, "\\xq1", 0, UNESCAPE_HEX, "\\xq1");
	/* \x at the very end of the string. */
	EXPECT_UNESCAPE(test, "\\x", 0, UNESCAPE_HEX, "\\x");
	EXPECT_UNESCAPE(test, "a\\x", 0, UNESCAPE_HEX, "a\\x");
}

static void agent_flags_gate_classes(struct kunit *test)
{
	const char *in = "\\n\\t\\101\\x41\\\"\\a";

	/* With no flags nothing is decoded. */
	EXPECT_UNESCAPE(test, in, 0, 0, "\\n\\t\\101\\x41\\\"\\a");
	EXPECT_UNESCAPE(test, in, 0, UNESCAPE_OCTAL,
			"\\n\\tA\\x41\\\"\\a");
	EXPECT_UNESCAPE(test, in, 0, UNESCAPE_HEX,
			"\\n\\t\\101A\\\"\\a");
	EXPECT_UNESCAPE(test, in, 0, UNESCAPE_SPACE,
			"\n\t\\101\\x41\\\"\\a");
	EXPECT_UNESCAPE(test, in, 0, UNESCAPE_SPECIAL,
			"\\n\\t\\101\\x41\"\a");
	EXPECT_UNESCAPE(test, in, 0, UNESCAPE_ANY,
			"\n\tA" "A\"\a");
}

static void agent_unknown_escapes(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\q", 0, UNESCAPE_ANY, "\\q");
	EXPECT_UNESCAPE(test, "\\b", 0, UNESCAPE_ANY, "\\b");
	EXPECT_UNESCAPE(test, "\\?", 0, UNESCAPE_ANY, "\\?");
	EXPECT_UNESCAPE(test, "\\'", 0, UNESCAPE_ANY, "\\'");
	EXPECT_UNESCAPE(test, "\\q\\b", 0, 0, "\\q\\b");
}

static void agent_escaped_backslash(struct kunit *test)
{
	/* "\\n" is a literal backslash followed by 'n', not a newline. */
	EXPECT_UNESCAPE(test, "\\\\n", 0, UNESCAPE_ANY, "\\n");
	EXPECT_UNESCAPE(test, "\\\\\\\\", 0, UNESCAPE_ANY, "\\\\");
	EXPECT_UNESCAPE(test, "\\\\101", 0, UNESCAPE_ANY, "\\101");
	EXPECT_UNESCAPE(test, "\\\\", 0, 0, "\\\\");
}

static void agent_trailing_backslash(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "\\", 0, UNESCAPE_ANY, "\\");
	EXPECT_UNESCAPE(test, "\\", 2, UNESCAPE_ANY, "\\");
	EXPECT_UNESCAPE(test, "abc\\", 0, UNESCAPE_ANY, "abc\\");
	EXPECT_UNESCAPE(test, "abc\\", 5, UNESCAPE_ANY, "abc\\");
	/* No room for the lone backslash: output stops before it. */
	EXPECT_UNESCAPE(test, "abc\\", 4, UNESCAPE_ANY, "abc");
}

static void agent_mixed_sequence(struct kunit *test)
{
	EXPECT_UNESCAPE(test,
			"Line1\\nLine2\\t\\x21\\101\\\"\\\\\\a\\e\\q",
			0, UNESCAPE_ANY,
			"Line1\nLine2\t!A\"\\\a\x1b\\q");
}

static void agent_in_place(struct kunit *test)
{
	char buf[] = "a\\tb\\x41\\\\";
	int ret;

	ret = string_unescape(buf, buf, sizeof(buf), UNESCAPE_ANY);

	KUNIT_EXPECT_EQ(test, ret, 5);
	KUNIT_EXPECT_EQ(test, memcmp(buf, "a\tbA\\", 5), 0);
	KUNIT_EXPECT_EQ(test, buf[5], '\0');
}

static void agent_size_zero_unlimited(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "abcdefghijklmnopqrstuvwxyz0123456789", 0,
			UNESCAPE_ANY,
			"abcdefghijklmnopqrstuvwxyz0123456789");
	EXPECT_UNESCAPE(test, "\\n\\t\\x41\\101", 0, UNESCAPE_ANY,
			"\n\tAA");
}

static void agent_size_one(struct kunit *test)
{
	/* A size of 1 leaves room only for the terminator. */
	EXPECT_UNESCAPE(test, "abc", 1, UNESCAPE_ANY, "");
	EXPECT_UNESCAPE(test, "\\n", 1, UNESCAPE_ANY, "");
	EXPECT_UNESCAPE(test, "\\n", 1, 0, "");
}

static void agent_size_truncates_plain(struct kunit *test)
{
	/* Input length is 6; a size of 6 holds only 5 characters. */
	EXPECT_UNESCAPE(test, "abcdef", 2, UNESCAPE_ANY, "a");
	EXPECT_UNESCAPE(test, "abcdef", 3, UNESCAPE_ANY, "ab");
	EXPECT_UNESCAPE(test, "abcdef", 4, UNESCAPE_ANY, "abc");
	EXPECT_UNESCAPE(test, "abcdef", 6, UNESCAPE_ANY, "abcde");
	EXPECT_UNESCAPE(test, "abcdef", 7, UNESCAPE_ANY, "abcdef");
	EXPECT_UNESCAPE(test, "abcdef", 100, UNESCAPE_ANY, "abcdef");
}

static void agent_size_exact_fit(struct kunit *test)
{
	EXPECT_UNESCAPE(test, "x", 2, UNESCAPE_ANY, "x");
	EXPECT_UNESCAPE(test, "x", 1, UNESCAPE_ANY, "");
}

static void agent_size_full_output_with_escapes(struct kunit *test)
{
	/* Output is never longer than input, so input length + 1 always fits. */
	EXPECT_UNESCAPE(test, "\\n\\t\\x41", 9, UNESCAPE_ANY, "\n\tA");
	EXPECT_UNESCAPE(test, "a\\nb", 5, UNESCAPE_ANY, "a\nb");
	EXPECT_UNESCAPE(test, "ab\\n", 5, UNESCAPE_ANY, "ab\n");
	EXPECT_UNESCAPE(test, "\\\\\\\\", 5, UNESCAPE_ANY, "\\\\");
}

static struct kunit_case agent_test_cases[] = {
