/*
 * Check memparse() on @str: the parsed value, and how many characters
 * were consumed (retptr - str).
 */
static void expect_memparse(struct kunit *test, const char *str,
			    unsigned long long value, size_t consumed)
{
	char *end = NULL;
	unsigned long long ret = memparse(str, &end);

	KUNIT_EXPECT_EQ_MSG(test, ret, value, "memparse(\"%s\") value", str);
	KUNIT_EXPECT_EQ_MSG(test, (size_t)(end - str), consumed,
			    "memparse(\"%s\") consumed", str);
}

static void memparse_plain_decimal(struct kunit *test)
{
	expect_memparse(test, "0", 0, 1);
	expect_memparse(test, "1", 1, 1);
	expect_memparse(test, "9", 9, 1);
	expect_memparse(test, "10", 10, 2);
	expect_memparse(test, "1024", 1024, 4);
	expect_memparse(test, "12345", 12345, 5);
}

static void memparse_radix_prefixes(struct kunit *test)
{
	/* Base 0: leading "0" is octal, "0x"/"0X" is hex. */
	expect_memparse(test, "010", 8, 3);
	expect_memparse(test, "0777", 511, 4);
	expect_memparse(test, "0x10", 16, 4);
	expect_memparse(test, "0XfF", 255, 4);
	expect_memparse(test, "0x10K", 16384, 5);
	expect_memparse(test, "010K", 8192, 4);
}

static void memparse_lowercase_suffixes(struct kunit *test)
{
	expect_memparse(test, "1k", 1ULL << 10, 2);
	expect_memparse(test, "1m", 1ULL << 20, 2);
	expect_memparse(test, "1g", 1ULL << 30, 2);
	expect_memparse(test, "1t", 1ULL << 40, 2);
	expect_memparse(test, "1p", 1ULL << 50, 2);
	expect_memparse(test, "1e", 1ULL << 60, 2);
}

static void memparse_uppercase_suffixes(struct kunit *test)
{
	expect_memparse(test, "1K", 1ULL << 10, 2);
	expect_memparse(test, "1M", 1ULL << 20, 2);
	expect_memparse(test, "1G", 1ULL << 30, 2);
	expect_memparse(test, "1T", 1ULL << 40, 2);
	expect_memparse(test, "1P", 1ULL << 50, 2);
	expect_memparse(test, "1E", 1ULL << 60, 2);
}

static void memparse_suffix_multipliers(struct kunit *test)
{
	/* Multipliers other than one, so a wrong shift count shows up. */
	expect_memparse(test, "2K", 2ULL << 10, 2);
	expect_memparse(test, "3M", 3ULL << 20, 2);
	expect_memparse(test, "5g", 5ULL << 30, 2);
	expect_memparse(test, "7T", 7ULL << 40, 2);
	expect_memparse(test, "9p", 9ULL << 50, 2);
	expect_memparse(test, "15E", 15ULL << 60, 3);
	expect_memparse(test, "1023K", 1023ULL << 10, 5);
	expect_memparse(test, "1023P", 1023ULL << 50, 5);
	expect_memparse(test, "0K", 0, 2);
	expect_memparse(test, "0E", 0, 2);
}

static void memparse_suffix_boundary_values(struct kunit *test)
{
	/* Values just below and just above a power of 1024. */
	expect_memparse(test, "1023", 1023, 4);
	expect_memparse(test, "1023M", 1023ULL << 20, 5);
	expect_memparse(test, "1025K", 1025ULL << 10, 5);
	expect_memparse(test, "1024K", 1ULL << 20, 5);
	expect_memparse(test, "1024M", 1ULL << 30, 5);
	expect_memparse(test, "1024G", 1ULL << 40, 5);
}

static void memparse_u64_max(struct kunit *test)
{
	expect_memparse(test, "18446744073709551615", ULLONG_MAX, 20);
	expect_memparse(test, "18446744073709551614", ULLONG_MAX - 1, 20);
	expect_memparse(test, "9223372036854775808", 1ULL << 63, 19);
}

static void memparse_stops_at_non_suffix(struct kunit *test)
{
	/* The first non-suffix char ends the number and is not consumed. */
	expect_memparse(test, "1x", 1, 1);
	expect_memparse(test, "1B", 1, 1);
	expect_memparse(test, "1 K", 1, 1);
	expect_memparse(test, "1,K", 1, 1);
	expect_memparse(test, "1Kx", 1024, 2);
	expect_memparse(test, "1KiB", 1024, 2);
	expect_memparse(test, "1MB", 1ULL << 20, 2);
	expect_memparse(test, "1GB", 1ULL << 30, 2);
}

static void memparse_consumes_one_suffix(struct kunit *test)
{
	/* Only a single suffix character is consumed. */
	expect_memparse(test, "1KK", 1024, 2);
	expect_memparse(test, "1M1K", 1ULL << 20, 2);
	expect_memparse(test, "1K2", 1024, 2);
	expect_memparse(test, "1K 2M", 1024, 2);
}

static void memparse_neighbouring_letters_are_not_suffixes(struct kunit *test)
{
	/* Every letter other than the suffixes must not scale the value. */
	static const char suffixes[] = "KMGTPEkmgtpe";
	char str[3] = { '1', 0, 0 };
	unsigned int c;

	for (c = 1; c < 128; c++) {
		char *end = NULL;
		unsigned long long ret;

		if (c >= '0' && c <= '9')
			continue;
		if (c && strchr(suffixes, (int)c))
			continue;

		str[1] = (char)c;
		ret = memparse(str, &end);

		KUNIT_EXPECT_EQ_MSG(test, ret, 1ULL, "char 0x%02x", c);
		KUNIT_EXPECT_EQ_MSG(test, (size_t)(end - str), 1UL,
				    "char 0x%02x consumed", c);
	}
}

static void memparse_no_digits(struct kunit *test)
{
	/* No digits: value 0, nothing consumed unless a suffix follows. */
	expect_memparse(test, "", 0, 0);
	expect_memparse(test, "abc", 0, 0);
	expect_memparse(test, "x", 0, 0);
	expect_memparse(test, "K", 0, 1);
	expect_memparse(test, "M", 0, 1);
	expect_memparse(test, "e", 0, 1);
}

