{
	KUNIT_EXPECT_EQ(test, memparse("4K", NULL), 4096ULL);
	KUNIT_EXPECT_EQ(test, memparse("2G", NULL), 2ULL << 30);
	KUNIT_EXPECT_EQ(test, memparse("17", NULL), 17ULL);
	KUNIT_EXPECT_EQ(test, memparse("", NULL), 0ULL);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(memparse_plain_decimal),
	KUNIT_CASE(memparse_radix_prefixes),
	KUNIT_CASE(memparse_lowercase_suffixes),
	KUNIT_CASE(memparse_uppercase_suffixes),
	KUNIT_CASE(memparse_suffix_multipliers),
	KUNIT_CASE(memparse_suffix_boundary_values),
	KUNIT_CASE(memparse_u64_max),
	KUNIT_CASE(memparse_stops_at_non_suffix),
	KUNIT_CASE(memparse_consumes_one_suffix),
	KUNIT_CASE(memparse_neighbouring_letters_are_not_suffixes),
	KUNIT_CASE(memparse_no_digits),
	KUNIT_CASE(memparse_null_retptr),
	{}
};

