/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Exercises __siphash_aligned() against a byte-at-a-time SipHash-2-4
 * reference, so that off-by-one errors in the block loop, the tail switch,
 * or the length encoding show up as mismatches.
 */

#include <kunit/test.h>
#include <linux/bitops.h>
#include <linux/siphash.h>
#include <linux/string.h>
#include <linux/types.h>

#define REF_SIPROUND do {						\
	v0 += v1; v1 = rol64(v1, 13); v1 ^= v0; v0 = rol64(v0, 32);	\
	v2 += v3; v3 = rol64(v3, 16); v3 ^= v2;				\
	v0 += v3; v3 = rol64(v3, 21); v3 ^= v0;				\
	v2 += v1; v1 = rol64(v1, 17); v1 ^= v2; v2 = rol64(v2, 32);	\
} while (0)

static const siphash_key_t test_key = {
	.key = { 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL },
};

/* Little-endian load of @n (<= 8) bytes, one byte at a time. */
static u64 ref_load_le(const u8 *p, size_t n)
{
	u64 r = 0;
	size_t i;

	for (i = 0; i < n; i++)
		r |= (u64)p[i] << (8 * i);
	return r;
}

/* Straightforward SipHash-2-4 over a byte buffer, independent of the kernel code. */
static u64 ref_siphash24(const u8 *in, size_t len, const siphash_key_t *key)
{
	u64 v0 = key->key[0] ^ 0x736f6d6570736575ULL;
	u64 v1 = key->key[1] ^ 0x646f72616e646f6dULL;
	u64 v2 = key->key[0] ^ 0x6c7967656e657261ULL;
	u64 v3 = key->key[1] ^ 0x7465646279746573ULL;
	size_t full = len - (len % 8);
	size_t i;
	u64 m, b;

	for (i = 0; i < full; i += 8) {
		m = ref_load_le(in + i, 8);
		v3 ^= m;
		REF_SIPROUND;
		REF_SIPROUND;
		v0 ^= m;
	}

	b = ((u64)len) << 56;
	b |= ref_load_le(in + full, len - full);
	v3 ^= b;
	REF_SIPROUND;
	REF_SIPROUND;
	v0 ^= b;
	v2 ^= 0xff;
	REF_SIPROUND;
	REF_SIPROUND;
	REF_SIPROUND;
	REF_SIPROUND;
	return v0 ^ v1 ^ v2 ^ v3;
}

/* Deterministic filler so failures are reproducible. */
static void fill_pattern(u8 *buf, size_t n, u32 seed)
{
	u32 x = seed * 2654435761u + 1;
	size_t i;

	for (i = 0; i < n; i++) {
		x ^= x << 13;
		x ^= x >> 17;
		x ^= x << 5;
		buf[i] = (u8)x;
	}
}

static void siphash_aligned_empty_known_answer(struct kunit *test)
{
	u8 buf[8] __aligned(8) = { 0 };

	/* SipHash-2-4 of the empty message under key 00..0f. */
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 0, &test_key),
			0x726fdb47dd0e0e31ULL);
	KUNIT_EXPECT_EQ(test, ref_siphash24(buf, 0, &test_key),
			0x726fdb47dd0e0e31ULL);
}

static void siphash_aligned_matches_reference_all_lengths(struct kunit *test)
{
	u8 buf[264] __aligned(8);
	size_t len;

	for (len = 0; len <= 256; len++) {
		fill_pattern(buf, len, (u32)len);
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(buf, len, &test_key),
				    ref_siphash24(buf, len, &test_key),
				    "len=%zu", len);
	}
}

static void siphash_aligned_block_boundaries(struct kunit *test)
{
	static const size_t lens[] = { 0, 1, 7, 8, 9, 15, 16, 17, 23, 24, 25,
				       63, 64, 65, 127, 128, 129 };
	u8 buf[136] __aligned(8);
	size_t i;

	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		fill_pattern(buf, lens[i], 0x5eed);
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(buf, lens[i], &test_key),
				    ref_siphash24(buf, lens[i], &test_key),
				    "len=%zu", lens[i]);
	}
}

static void siphash_aligned_tail_lengths(struct kunit *test)
{
	u8 buf[32] __aligned(8);
	size_t blocks, tail, len;

	/* Every partial tail (1..7 bytes) after 0..3 full words. */
	for (blocks = 0; blocks <= 3; blocks++) {
		for (tail = 1; tail <= 7; tail++) {
			len = blocks * 8 + tail;
			fill_pattern(buf, len, (u32)len * 7 + 3);
			KUNIT_EXPECT_EQ_MSG(test,
					    __siphash_aligned(buf, len, &test_key),
					    ref_siphash24(buf, len, &test_key),
					    "len=%zu", len);
		}
	}
}

static void siphash_aligned_ignores_bytes_past_end(struct kunit *test)
{
	u8 buf[64] __aligned(8);
	size_t len;

	/* Bytes beyond @len must not leak into the tail word. */
	for (len = 0; len <= 40; len++) {
		u64 h1, h2;

		fill_pattern(buf, len, (u32)len + 5);
		memset(buf + len, 0xaa, sizeof(buf) - len);
		h1 = __siphash_aligned(buf, len, &test_key);
		memset(buf + len, 0x55, sizeof(buf) - len);
		h2 = __siphash_aligned(buf, len, &test_key);
		KUNIT_EXPECT_EQ_MSG(test, h1, h2, "len=%zu", len);
	}
}

static void siphash_aligned_every_byte_affects_hash(struct kunit *test)
{
	u8 buf[40] __aligned(8);
	size_t len, i;

	/* Flipping any byte inside [0, len) must change the result. */
	for (len = 1; len <= 40; len++) {
		u64 base;

		fill_pattern(buf, len, (u32)len + 99);
		base = __siphash_aligned(buf, len, &test_key);
		for (i = 0; i < len; i++) {
			buf[i] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test,
					    __siphash_aligned(buf, len, &test_key),
					    base, "len=%zu byte=%zu", len, i);
			buf[i] ^= 0x01;
		}
	}
}

static void siphash_aligned_key_words_both_used(struct kunit *test)
{
	u8 buf[21] __aligned(8);
	siphash_key_t key;
	size_t len;

	for (len = 0; len <= 20; len += 5) {
		fill_pattern(buf, len, (u32)len + 1);

		key = test_key;
		key.key[0] ^= 1;
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(buf, len, &key),
				    ref_siphash24(buf, len, &key),
				    "key[0] len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, __siphash_aligned(buf, len, &key),
				    __siphash_aligned(buf, len, &test_key),
				    "key[0] len=%zu", len);

		key = test_key;
		key.key[1] ^= 1ULL << 63;
		KUNIT_EXPECT_EQ_MSG(test, __siphash_aligned(buf, len, &key),
				    ref_siphash24(buf, len, &key),
				    "key[1] len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test, __siphash_aligned(buf, len, &key),
				    __siphash_aligned(buf, len, &test_key),
				    "key[1] len=%zu", len);
	}
}

static void siphash_aligned_length_is_mixed_in(struct kunit *test)
{
	u8 buf[48] __aligned(8);
	u64 hashes[41];
	size_t i, j;

	/* All-zero inputs of different lengths must hash differently. */
	memset(buf, 0, sizeof(buf));
	for (i = 0; i <= 40; i++)
		hashes[i] = __siphash_aligned(buf, i, &test_key);

	for (i = 0; i <= 40; i++)
		for (j = i + 1; j <= 40; j++)
			KUNIT_EXPECT_NE_MSG(test, hashes[i], hashes[j],
					    "lens %zu and %zu collide", i, j);
}

static void siphash_aligned_agrees_with_unaligned_variant(struct kunit *test)
{
	u8 buf[136] __aligned(8);
	size_t len;

	for (len = 0; len <= 128; len++) {
		fill_pattern(buf, len, (u32)len * 31 + 7);
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(buf, len, &test_key),
				    __siphash_unaligned(buf, len, &test_key),
				    "len=%zu", len);
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(siphash_aligned_empty_known_answer),
	KUNIT_CASE(siphash_aligned_matches_reference_all_lengths),
	KUNIT_CASE(siphash_aligned_block_boundaries),
	KUNIT_CASE(siphash_aligned_tail_lengths),
	KUNIT_CASE(siphash_aligned_ignores_bytes_past_end),
	KUNIT_CASE(siphash_aligned_every_byte_affects_hash),
	KUNIT_CASE(siphash_aligned_key_words_both_used),
	KUNIT_CASE(siphash_aligned_length_is_mixed_in),
	KUNIT_CASE(siphash_aligned_agrees_with_unaligned_variant),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
