static const hsiphash_key_t agent_keys[] = {
	{{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }},
	{{ 0, 0 }},
	{{ ~0ULL, 0x0123456789abcdefULL }},
};

static u64 agent_next(u64 *state)
{
	u64 x = *state;

	x ^= x << 13;
	x ^= x >> 7;
	x ^= x << 17;
	*state = x;
	return x;
}

static void agent_fill(u8 *buf, size_t n, u64 seed)
{
	u64 state = seed * 0x9e3779b97f4a7c15ULL | 1;
	size_t i;

	for (i = 0; i < n; i++)
		buf[i] = agent_next(&state) & 0xff;
}

static u64 agent_le64(const u8 *p)
{
	u64 v = 0;
	int i;

	for (i = 7; i >= 0; i--)
		v = (v << 8) | p[i];
	return v;
}

static void agent_sipround(u64 *v0, u64 *v1, u64 *v2, u64 *v3)
{
	*v0 += *v1; *v1 = rol64(*v1, 13); *v1 ^= *v0; *v0 = rol64(*v0, 32);
	*v2 += *v3; *v3 = rol64(*v3, 16); *v3 ^= *v2;
	*v0 += *v3; *v3 = rol64(*v3, 21); *v3 ^= *v0;
	*v2 += *v1; *v1 = rol64(*v1, 17); *v1 ^= *v2; *v2 = rol64(*v2, 32);
}

/*
 * Straightforward byte-wise SipHash-1-3 with a 32-bit truncated output:
 * one compression round per 8-byte block, the trailing bytes plus length
 * in the top byte as the final block, then 3 finalization rounds.
 */
static u32 agent_ref_hsiphash(const u8 *data, size_t len,
			      const hsiphash_key_t *key)
{
	u64 v0 = 0x736f6d6570736575ULL ^ key->key[0];
	u64 v1 = 0x646f72616e646f6dULL ^ key->key[1];
	u64 v2 = 0x6c7967656e657261ULL ^ key->key[0];
	u64 v3 = 0x7465646279746573ULL ^ key->key[1];
	u64 m, b;
	size_t i, j, left;

	for (i = 0; i + 8 <= len; i += 8) {
		m = agent_le64(data + i);
		v3 ^= m;
		agent_sipround(&v0, &v1, &v2, &v3);
		v0 ^= m;
	}

	left = len - i;
	b = (u64)len << 56;
	for (j = 0; j < left; j++)
		b |= (u64)data[i + j] << (8 * j);

	v3 ^= b;
	agent_sipround(&v0, &v1, &v2, &v3);
	v0 ^= b;
	v2 ^= 0xff;
	agent_sipround(&v0, &v1, &v2, &v3);
	agent_sipround(&v0, &v1, &v2, &v3);
	agent_sipround(&v0, &v1, &v2, &v3);

	return (u32)((v0 ^ v1) ^ (v2 ^ v3));
}

static void agent_known_answers(struct kunit *test)
{
	u8 in[64] __aligned(SIPHASH_ALIGNMENT);
	size_t i;

	for (i = 0; i < 64; i++)
		in[i] = i;

	for (i = 0; i < ARRAY_SIZE(agent_kat); i++)
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(in, i, &agent_kat_key),
				    agent_kat[i], "len %zu", i);
}

static void agent_matches_reference(struct kunit *test)
{
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
	size_t k, len;

	agent_fill(buf, sizeof(buf), 1);
	for (k = 0; k < ARRAY_SIZE(agent_keys); k++)
		for (len = 0; len <= 256; len++)
			KUNIT_EXPECT_EQ_MSG(test,
					    __hsiphash_aligned(buf, len,
							       &agent_keys[k]),
					    agent_ref_hsiphash(buf, len,
							       &agent_keys[k]),
					    "key %zu len %zu", k, len);
}

static void agent_matches_unaligned_variant(struct kunit *test)
{
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
	size_t k, len;

	agent_fill(buf, sizeof(buf), 2);
	for (k = 0; k < ARRAY_SIZE(agent_keys); k++)
		for (len = 0; len <= 256; len++)
			KUNIT_EXPECT_EQ_MSG(test,
					    __hsiphash_aligned(buf, len,
							       &agent_keys[k]),
					    __hsiphash_unaligned(buf, len,
								 &agent_keys[k]),
					    "key %zu len %zu", k, len);
}

static void agent_block_boundary_lengths(struct kunit *test)
{
	static const size_t lens[] = {
		1, 7, 8, 9, 15, 16, 17, 23, 24, 25, 31, 32, 33,
		63, 64, 65, 127, 128, 129, 255, 256, 257,
	};
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
	size_t i;

	agent_fill(buf, sizeof(buf), 3);
	for (i = 0; i < ARRAY_SIZE(lens); i++)
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(buf, lens[i],
						       &agent_keys[0]),
				    agent_ref_hsiphash(buf, lens[i],
						       &agent_keys[0]),
				    "len %zu", lens[i]);
}

static void agent_zero_length(struct kunit *test)
{
	u8 zeros[16] __aligned(SIPHASH_ALIGNMENT) = { 0 };
	u8 noise[16] __aligned(SIPHASH_ALIGNMENT);

	agent_fill(noise, sizeof(noise), 4);

	/* With len == 0 the data must not contribute at all. */
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(zeros, 0, &agent_keys[0]),
			__hsiphash_aligned(noise, 0, &agent_keys[0]));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(zeros, 0, &agent_keys[0]),
			agent_kat[0]);
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(zeros, 0, &agent_keys[0]),
			agent_ref_hsiphash(zeros, 0, &agent_keys[0]));
}

static void agent_bytes_beyond_length_ignored(struct kunit *test)
{
	u8 buf[96] __aligned(SIPHASH_ALIGNMENT);
	u32 before;
	size_t len, j;

	agent_fill(buf, sizeof(buf), 5);
	for (len = 0; len <= 80; len++) {
		before = __hsiphash_aligned(buf, len, &agent_keys[0]);
		for (j = len; j < sizeof(buf); j++)
			buf[j] = ~buf[j];
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(buf, len, &agent_keys[0]),
				    before, "len %zu", len);
		agent_fill(buf, sizeof(buf), 5);
	}
}

static void agent_every_byte_affects_hash(struct kunit *test)
{
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
	u32 base;
	size_t len, j;

	agent_fill(buf, sizeof(buf), 6);
	for (len = 1; len <= 70; len++) {
		base = __hsiphash_aligned(buf, len, &agent_keys[0]);
		for (j = 0; j < len; j++) {
			buf[j] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test,
					    __hsiphash_aligned(buf, len,
							       &agent_keys[0]),
					    base, "len %zu byte %zu", len, j);
			buf[j] ^= 0x01;
		}
	}
}

static void agent_length_is_mixed_in(struct kunit *test)
{
	u8 zeros[65] __aligned(SIPHASH_ALIGNMENT) = { 0 };
	size_t len;

	/*
	 * Trailing zero bytes are indistinguishable from padding unless the
	 * length is part of the final block, so each extension must differ.
	 */
	for (len = 0; len <= 64; len++)
		KUNIT_EXPECT_NE_MSG(test,
				    __hsiphash_aligned(zeros, len,
						       &agent_keys[0]),
				    __hsiphash_aligned(zeros, len + 1,
						       &agent_keys[0]),
				    "len %zu vs %zu", len, len + 1);
}

static void agent_key_words_affect_hash(struct kunit *test)
{
	u8 buf[64] __aligned(SIPHASH_ALIGNMENT);
	hsiphash_key_t key = agent_keys[0];
	hsiphash_key_t key_lo = agent_keys[0];
	hsiphash_key_t key_hi = agent_keys[0];
	size_t len;

	agent_fill(buf, sizeof(buf), 7);
	key_lo.key[0] ^= 1;
	key_hi.key[1] ^= 1ULL << 63;

	for (len = 0; len <= 40; len++) {
		KUNIT_EXPECT_NE_MSG(test,
				    __hsiphash_aligned(buf, len, &key),
				    __hsiphash_aligned(buf, len, &key_lo),
				    "key[0] len %zu", len);
		KUNIT_EXPECT_NE_MSG(test,
				    __hsiphash_aligned(buf, len, &key),
				    __hsiphash_aligned(buf, len, &key_hi),
				    "key[1] len %zu", len);
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(buf, len, &key_lo),
				    agent_ref_hsiphash(buf, len, &key_lo),
				    "key_lo len %zu", len);
	}
}

static void agent_large_lengths(struct kunit *test)
{
	static const size_t lens[] = {
		300, 511, 512, 513, 1000, 1199, 1200,
	};
	u8 buf[AGENT_BUF_SIZE] __aligned(SIPHASH_ALIGNMENT);
	size_t i;

	agent_fill(buf, sizeof(buf), 8);
	for (i = 0; i < ARRAY_SIZE(lens); i++)
		KUNIT_EXPECT_EQ_MSG(test,
				    __hsiphash_aligned(buf, lens[i],
						       &agent_keys[2]),
				    agent_ref_hsiphash(buf, lens[i],
						       &agent_keys[2]),
				    "len %zu", lens[i]);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_known_answers),
	KUNIT_CASE(agent_matches_reference),
	KUNIT_CASE(agent_matches_unaligned_variant),
	KUNIT_CASE(agent_block_boundary_lengths),
	KUNIT_CASE(agent_zero_length),
	KUNIT_CASE(agent_bytes_beyond_length_ignored),
	KUNIT_CASE(agent_every_byte_affects_hash),
	KUNIT_CASE(agent_length_is_mixed_in),
	KUNIT_CASE(agent_key_words_affect_hash),
	KUNIT_CASE(agent_large_lengths),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

